class GraphConvLayer(nn.Module):
    def __init__(self, atom_fea_len, nbr_fea_len):
        super(GraphConvLayer, self).__init__()
        self.atom_fea_len = atom_fea_len
        self.nbr_fea_len = nbr_fea_len
        self.fc_full = nn.Linear(2*self.atom_fea_len+self.nbr_fea_len,
                                 2*self.atom_fea_len)
        self.sigmoid = nn.Sigmoid()
        self.softplus1 = nn.Softplus()
        self.bn1 = nn.BatchNorm1d(2*self.atom_fea_len)
        self.bn2 = nn.BatchNorm1d(self.atom_fea_len)
        self.softplus2 = nn.Softplus()

    def forward(self, atom_in_fea, nbr_fea, nbr_fea_idx):
        N, M = nbr_fea_idx.shape
        atom_nbr_fea = atom_in_fea[nbr_fea_idx, :]
        total_nbr_fea = torch.cat(
            [atom_in_fea.unsqueeze(1).expand(N, M, self.atom_fea_len),
             atom_nbr_fea, nbr_fea], dim=2)
        total_gated_fea = self.fc_full(total_nbr_fea)
        total_gated_fea = self.bn1(total_gated_fea.view(
            -1, self.atom_fea_len*2)).view(N, M, self.atom_fea_len*2)
        nbr_filter, nbr_core = total_gated_fea.chunk(2, dim=2)
        nbr_filter = self.sigmoid(nbr_filter)
        nbr_core = self.softplus1(nbr_core)
        nbr_sumed = torch.sum(nbr_filter * nbr_core, dim=1)
        nbr_sumed = self.bn2(nbr_sumed)
        out = self.softplus2(atom_in_fea + nbr_sumed)
        return out


class GraphPooling(nn.Module):
    def __init__(self):
        super(GraphPooling, self).__init__()

    def forward(self, atom_fea, crystal_atom_idx):
        assert sum([len(idx_map) for idx_map in crystal_atom_idx]) == atom_fea.data.shape[0]
        summed_fea = [torch.mean(atom_fea[idx_map], dim=0, keepdim=True)
                      for idx_map in crystal_atom_idx]
        return torch.cat(summed_fea, dim=0)


class CrystalGraphConvNet(nn.Module):
    def __init__(self, orig_atom_fea_len, nbr_fea_len,
                 atom_fea_len=60, h_fea_len=30):
        super(CrystalGraphConvNet, self).__init__()
        self.embedding = nn.Linear(orig_atom_fea_len, atom_fea_len)
        self.relu1 = nn.ReLU()
        self.conv1 = GraphConvLayer(atom_fea_len=atom_fea_len, nbr_fea_len=nbr_fea_len)
        self.relu2 = nn.ReLU()
        self.conv2 = GraphConvLayer(atom_fea_len=atom_fea_len, nbr_fea_len=nbr_fea_len)
        self.relu3 = nn.ReLU()
        self.conv3 = GraphConvLayer(atom_fea_len=atom_fea_len, nbr_fea_len=nbr_fea_len)
        self.pooling = GraphPooling()
        self.relu4 = nn.ReLU()
        self.conv_to_fc = nn.Linear(atom_fea_len, h_fea_len)
        self.relu5 = nn.ReLU()
        self.fc_out = nn.Linear(h_fea_len, 2)

    def forward(self, atom_fea, nbr_fea, nbr_fea_idx, crystal_atom_idx):
        atom_fea = self.embedding(atom_fea)
        atom_fea = self.relu1(atom_fea)
        atom_fea = self.conv1(atom_fea, nbr_fea, nbr_fea_idx)
        atom_fea = self.conv2(atom_fea, nbr_fea, nbr_fea_idx)
        atom_fea = self.conv3(atom_fea, nbr_fea, nbr_fea_idx)
        crys_fea = self.pooling(atom_fea, crystal_atom_idx)
        crys_fea = self.conv_to_fc(crys_fea)
        crys_fea = self.relu5(crys_fea)
        out = self.fc_out(crys_fea)

        return out


class ElasticML:
    STD = torch.FloatTensor([88.7647, 0.1142])
    MEAN = torch.FloatTensor([109.2043, 0.2731])

    MODELNAME = Path(__file__).parent/"model_hf73kd992kz.pt"

    RADIUS = 8
    MAX_NUM_NBR = 12
    STEP = 0.2

    propertyExtension = ElasticMLFunctions

    def __init__(self):
        with open(self.MODELNAME, "rb") as f:
            self.model = torch.load(f)

    def predictValues(self, system: EntryFlavour):
        """
        Predict values of E and nu using neural network from doi.org/10.1063/5.0012055
        """

        structure = system['atomistic.structure']
        cell = structure.getCell()
        assert cell.getPBC() == (1, 1, 1), "Model works only for 3D crystals."
        crystal = Structure(species=[el.short_name for el in structure.getAtomTypes()],
                            coords=structure.getCartesianCoordinates(),
                            lattice=cell.getCellVectors())

        atom_features = torch.Tensor(np.vstack([EMBEDDINGS[crystal[i].specie.number-1] for i in range(len(crystal))]))
        all_nums = torch.LongTensor(np.arange(atom_features.shape[0]))
        all_nbrs = crystal.get_all_neighbors(self.RADIUS, include_index=True)
        all_nbrs = [sorted(nbrs, key=lambda x: x[1]) for nbrs in all_nbrs]
        nbr_features_idx = torch.LongTensor([list(map(lambda x: x[2], nbr[:self.MAX_NUM_NBR])) for nbr in all_nbrs])
        nbr_features = np.array([list(map(lambda x: x[1], nbr[:self.MAX_NUM_NBR])) for nbr in all_nbrs])
        nbr_features = torch.Tensor(np.exp(-(nbr_features[..., np.newaxis]-np.arange(0, self.RADIUS+self.STEP, self.STEP))**2/self.STEP**2))
        nbr_features_idx = torch.LongTensor(nbr_features_idx)
        output = self.model(atom_features, nbr_features, nbr_features_idx, [all_nums])

        E, nu = (self.MEAN + self.STD*output)[0].data
        E = float(E)
        nu = float(nu)
        V0 = crystal.volume / len(crystal.sites)

        system.setProperty('youngsModulus', E, extension='elasticML')
        system.setProperty('poissonsRatio', nu, extension='elasticML')
        system.setProperty('bulkModulus', E/(3*(1-2*nu)), extension='elasticML')
        system.setProperty('shearModulus', E/(2*(1+nu)), extension='elasticML')
        system.setProperty('pughsRatio', 3*(1-2*nu)/(2*(1+nu)), extension='elasticML')
        system.setProperty('vickersHardness', 0.096*E*(1 - 8.5*nu + 19.5*nu**2)/(1 - 7.5*nu + 12.2*nu**2 + 19.6*nu**3),
                           extension='elasticML')
        system.setProperty('fractureToughness', (10**-2)*(8840**-0.5)*(V0**(1/6)) *
                                                (E*(1-13.7*nu+48.6*nu**2)/(1-15.2*nu+70.2*nu**2-81.5*nu**3))**1.5,
                           extension='elasticML')
        return
